function getSpellOrRuneDamage(idOrWords, isRune) {
                    const level = playerState.level;
                    const magicLevel = getEffectiveSkill('magic');
                    let min = 0;
                    let max = 0;

                    if (isRune) {
                        const runeId = parseInt(idOrWords);
                        if (runeId === 2268) { // SD
                            min = (level / 5) + (magicLevel * 4.3) + 32;
                            max = (level / 5) + (magicLevel * 7.4) + 48;
                        } else if (runeId === 2304) { // GFB
                            min = (level / 5) + (magicLevel * 1.2) + 7;
                            max = (level / 5) + (magicLevel * 2.85) + 16;
                        } else if (runeId === 2313) { // Explosion
                            min = (level / 5) + (magicLevel * 1.6) + 9;
                            max = (level / 5) + (magicLevel * 3.2) + 19;
                        } else if (runeId === 2311) { // HMM
                            min = (level / 5) + (magicLevel * 0.8) + 5;
                            max = (level / 5) + (magicLevel * 1.6) + 10;
                        } else if (runeId === 2287) { // LMM
                            min = (level / 5) + (magicLevel * 0.4) + 3;
                            max = (level / 5) + (magicLevel * 0.8) + 5;
                        // Runas elementais — espelho exato de idleRollRuneAttackDamage() no PHP
                        } else if (runeId === 2274) { // Avalanche (gelo, área)
                            min = (level / 5) + (magicLevel * 1.2) + 7;
                            max = (level / 5) + (magicLevel * 2.85) + 16;
                        } else if (runeId === 2288) { // Stone Shower (terra, área)
                            min = (level / 5) + (magicLevel * 1.1) + 6;
                            max = (level / 5) + (magicLevel * 2.6) + 14;
                        } else if (runeId === 2315) { // Thunderstorm (energia, área)
                            min = (level / 5) + (magicLevel * 1.1) + 6;
                            max = (level / 5) + (magicLevel * 2.6) + 14;
                        } else if (runeId === 2302) { // Fireball (fogo, área)
                            min = (level / 5) + (magicLevel * 0.9) + 5;
                            max = (level / 5) + (magicLevel * 2.1) + 12;
                        } else if (runeId === 2271) { // Icicle (gelo, alvo único)
                            min = (level / 5) + (magicLevel * 1.5) + 8;
                            max = (level / 5) + (magicLevel * 3.0) + 18;
                        } else if (runeId === 2295) { // Holy Missile (sagrado, alvo único)
                            min = (level / 5) + (magicLevel * 1.5) + 8;
                            max = (level / 5) + (magicLevel * 3.0) + 18;
                        }
                    } else {
                        const words = idOrWords.toLowerCase().trim();
                        const spellMeta = spellsDb[words] || {};
                        const formula = spellMeta.formula || null;

                        const formulaTermValue = (term) => {
                            if (!term) return 0;
                            const formulaLevel = formula && formula.levelCap ? Math.min(level, parseInt(formula.levelCap, 10) || level) : level;
                            const formulaMagicLevel = formula && formula.magicLevelCap ? Math.min(magicLevel, parseInt(formula.magicLevelCap, 10) || magicLevel) : magicLevel;
                            let value = parseFloat(term.constant || 0) || 0;
                            const divisor = parseFloat(term.levelDivisor || 0) || 0;
                            if (divisor > 0) value += formulaLevel / divisor;
                            value += formulaMagicLevel * (parseFloat(term.magicLevel || 0) || 0);
                            value += getEffectiveSkill('distance') * (parseFloat(term.distanceSkill || 0) || 0);

                            const skillAttackFactor = parseFloat(term.skillAttack || 0) || 0;
                            if (skillAttackFactor > 0) {
                                const skillKey = getEquippedWeaponSkillKey() || 'sword_tries';
                                const weaponSkill = Math.max(10, getEffectiveSkill(skillKey.replace('_tries', '')));
                                const weaponId = playerEquip.weapon ? playerEquip.weapon.id : 0;
                                const weaponMeta = weaponId ? getItemInstanceMeta(playerEquip.weapon) : {};

                                let weaponAttack = getItemAttackValue(weaponMeta);
                                if (weaponUsesAmmunition(weaponMeta) && getVocationBase(playerState.vocation) === 'paladin') {
                                    const requiredAmmoType = getRequiredAmmoTypeForWeapon(weaponMeta);
                                    const ammoId = playerEquip.ammo ? playerEquip.ammo.id : 0;
                                    const ammoMeta = ammoId ? getItemInstanceMeta(playerEquip.ammo) : null;
                                    if (ammoMeta && requiredAmmoType && getAmmoItemType(ammoMeta) === requiredAmmoType) {
                                        weaponAttack += getItemAttackValue(ammoMeta);
                                    }
                                }
                                if (weaponAttack <= 0) weaponAttack = 25;
                                value += weaponSkill * weaponAttack * skillAttackFactor;
                            }

                            return Math.max(0, value);
                        };

                        if (formula && formula.min && formula.max) {
                            min = formulaTermValue(formula.min);
                            max = formulaTermValue(formula.max);
                        } else if (['exori', 'exori ico', 'exori gran'].includes(words)) {
                            // Knight spells scale on Melee Skill and Weapon Attack
                            const meleeSkill = Math.max(10, getEffectiveSkill((getEquippedWeaponSkillKey() || 'sword_tries').replace('_tries', '')));

                            const weaponId = playerEquip.weapon ? playerEquip.weapon.id : 0;
                            const weaponMeta = weaponId ? getItemInstanceMeta(playerEquip.weapon) : {};
                            let weaponAttack = 0;
                            if (weaponMeta.attributes) {
                                weaponAttack = parseInt(weaponMeta.attributes.attack || 0);
                            } else {
                                weaponAttack = parseInt(weaponMeta.attack || 0);
                            }
                            if (weaponAttack <= 0) weaponAttack = 5;

                            if (words === 'exori') {
                                min = (level / 5) + (meleeSkill * weaponAttack * 0.03) + 7;
                                max = (level / 5) + (meleeSkill * weaponAttack * 0.05) + 11;
                            } else if (words === 'exori ico') {
                                min = (level / 5) + (meleeSkill * weaponAttack * 0.02) + 4;
                                max = (level / 5) + (meleeSkill * weaponAttack * 0.04) + 9;
                            } else if (words === 'exori gran') {
                                min = (level / 5) + (meleeSkill * weaponAttack * 0.06) + 13;
                                max = (level / 5) + (meleeSkill * weaponAttack * 0.11) + 27;
                            }
                        } else if (words === 'exori san') {
                            min = (level / 5) + (magicLevel * 1.9) + 8;
                            max = (level / 5) + (magicLevel * 3.0) + 18;
                        } else if (['exori con', 'exori gran con'].includes(words)) {
                            // Paladin physical spear spells scale on Distance Skill, total weapon/ammo attack, and Magic Level
                            const distSkill = Math.max(10, getEffectiveSkill('distance_tries'));
                            const weaponId = playerEquip.weapon ? playerEquip.weapon.id : 0;
                            const weaponMeta = weaponId ? getItemInstanceMeta(playerEquip.weapon) : {};

                            let weaponAttack = getItemAttackValue(weaponMeta);
                            if (weaponUsesAmmunition(weaponMeta) && getVocationBase(playerState.vocation) === 'paladin') {
                                const requiredAmmoType = getRequiredAmmoTypeForWeapon(weaponMeta);
                                const ammoId = playerEquip.ammo ? playerEquip.ammo.id : 0;
                                const ammoMeta = ammoId ? getItemInstanceMeta(playerEquip.ammo) : null;
                                if (ammoMeta && requiredAmmoType && getAmmoItemType(ammoMeta) === requiredAmmoType) {
                                    weaponAttack += getItemAttackValue(ammoMeta);
                                }
                            }
                            if (weaponAttack <= 0) weaponAttack = 25;

                            if (words === 'exori con') {
                                min = (level / 5) + (distSkill * weaponAttack * 0.04) + (magicLevel * 1.2) + 15;
                                max = (level / 5) + (distSkill * weaponAttack * 0.08) + (magicLevel * 2.2) + 30;
                            } else if (words === 'exori gran con') {
                                // Exori Gran Con: Magia pesadíssima de dano único do Paladin (Lvl 90, 8s cd, ~3x do dano base)
                                min = (level / 5) + (distSkill * 5.5) + (magicLevel * 4.0) + 120;
                                max = (level / 5) + (distSkill * 9.5) + (magicLevel * 8.0) + 220;
                            }
                        } else if (words === 'exevo mas san') {
                            min = (level / 5) + (magicLevel * 5.0) + 25;
                            max = (level / 5) + (magicLevel * 6.2) + 45;
                        } else if (['exori flam', 'exori vis', 'exori frigo', 'exori mort'].includes(words)) {
                            min = (level / 5) + (magicLevel * 1.4) + 8;
                            max = (level / 5) + (magicLevel * 2.2) + 14;
                        } else if (words === 'exevo gran mas vis') {
                            min = (level / 5) + (magicLevel * 4.0) + 75;
                            max = (level / 5) + (magicLevel * 10.0) + 150;
                        } else if (words === 'exevo gran mas frigo') {
                            min = (level / 5) + (magicLevel * 5.5) + 25;
                            max = (level / 5) + (magicLevel * 11.0) + 50;
                        } else if (words === 'exevo flam hur' || words === 'exevo frigo hur') {
                            // Fire Wave / Ice Wave (ticket #0127): magias de ONDA em área. Antes NÃO
                            // tinham fórmula e caíam no fallback físico (por causa do 'hur'), escalando
                            // com ataque de arma (5 numa varinha) = dano ridículo, abaixo da GFB. Agora
                            // escalam com Magic Level, ACIMA da GFB (que é ML*1.2..2.85), como convém a
                            // uma magia de maestria da Roda. Espelho em idleEstimateSpellDamageRange (PHP).
                            min = (level / 5) + (magicLevel * 1.6) + 10;
                            max = (level / 5) + (magicLevel * 3.2) + 22;
                        } else if (words === 'exevo vis hur' || words === 'exevo tera hur') {
                            // Energy Wave / Earth Wave: nível 38, mais mana e cooldown maior — escala
                            // mais forte que Fire/Ice Wave. Também espelhado no servidor.
                            min = (level / 5) + (magicLevel * 2.2) + 15;
                            max = (level / 5) + (magicLevel * 4.4) + 30;
                        }

                        if (min <= 0 || max <= 0) {
                            const baseVoc = playerState.vocation > 4 ? playerState.vocation - 4 : playerState.vocation;
                            const spellLevel = parseInt(spellMeta.level || 1, 10) || 1;
                            const spellMana = parseInt(spellMeta.mana || 0, 10) || 0;
                            const spellName = (spellMeta.name || '').toLowerCase();
                            const isPhysical = baseVoc === 4
                                || words.includes('ico')
                                || words.includes('mas')
                                || words.includes('hur')
                                || words.includes('con')
                                || spellName.includes('spear')
                                || spellName.includes('sweep')
                                || spellName.includes('berserk')
                                || spellName.includes('throw')
                                || spellName.includes('wound');

                            if (isPhysical && baseVoc !== 1 && baseVoc !== 2) {
                                const skillKey = getEquippedWeaponSkillKey() || 'sword_tries';
                                const weaponSkill = Math.max(10, getEffectiveSkill(skillKey.replace('_tries', '')));
                                const weaponId = playerEquip.weapon ? playerEquip.weapon.id : 0;
                                const weaponMeta = weaponId ? getItemInstanceMeta(playerEquip.weapon) : {};
                                const attrs = weaponMeta.attributes || {};
                                const weaponAttack = Math.max(5, parseInt(weaponMeta.attack ?? attrs.attack ?? 0, 10) || 0);
                                let physicalScale = 0.025;
                                if (words.includes('gran')) physicalScale = 0.05;
                                if (words.includes('mas')) physicalScale = 0.045;
                                if (words.includes('max')) physicalScale = 0.075;
                                min = (level / 5) + (weaponSkill * weaponAttack * physicalScale) + Math.max(4, spellLevel * 0.25);
                                max = (level / 5) + (weaponSkill * weaponAttack * (physicalScale * 1.8)) + Math.max(8, spellMana * 0.12);
                            } else {
                                let spellScale = 1.15;
                                if (words.includes('infir')) spellScale = 0.65;
                                if (words.includes('gran')) spellScale += 0.75;
                                if (words.includes('max')) spellScale += 1.4;
                                if (words.includes('mas')) spellScale += 1.0;
                                if (words.includes('hur')) spellScale += 0.55;
                                if (words.includes('lux')) spellScale += 0.6;
                                if (words.startsWith('utori')) spellScale = 0.9;
                                min = (level / 5) + (magicLevel * spellScale) + Math.max(3, spellLevel * 0.3);
                                max = (level / 5) + (magicLevel * (spellScale * 1.75)) + Math.max(6, spellMana * 0.18);
                            }
                        }
                    }

                    if (min <= 0) min = 1;
                    if (max < min) max = min + 1;

                    // Scale damage based on combat posture / mode (FIGHTMODE multipliers on getAttackFactor)
                    const mode = playerState.combatMode || 'balanced';
                    let attackFactor = 1.0;
                    if (mode === 'balanced') attackFactor = 1.2;
                    else if (mode === 'defense') attackFactor = 2.0;

                    // Attack factor is the denominator in the OTServ formula, so divide by it
                    min = min / attackFactor;
                    max = max / attackFactor;

                    // Sorcerer/Druid causam ~25% de dano a mais no geral (espelha o mesmo bônus
                    // aplicado no dps de equipamento server-side, calculateEquipmentStats) —
                    // runas e magias de ataque/cura entram aqui também, não só o dps genérico.
                    // Ajuste de balanceamento (2026-07-30): desbalanceado entre as duas classes —
                    // Sorcerer +10% em cima da base (1.25*1.10=1.375), Druid +20% em cima da base
                    // (1.25*1.20=1.50). Espelho de calculateEquipmentStats() no PHP; os dois têm
                    // que mudar juntos.
                    // ⚠️ 2026-08-01: os dois voltaram para 1.25 (base histórica). Motivo completo
                    // no espelho em calculateEquipmentStats() no PHP — medição de produção com os
                    // nerfs de Knight/Paladin já revertidos deu knight/paladino ~110kk/h contra
                    // ~330kk/h do sorcerer. Trocar os DOIS lados sempre juntos.
                    const dmgBaseVoc = playerState.vocation > 4 ? playerState.vocation - 4 : playerState.vocation;
                    if (dmgBaseVoc === 1 || dmgBaseVoc === 2) {
                        min *= 1.25;
                        max *= 1.25;
                    }

                    // ── CORTE DAS MAGIAS DE ÁREA DA MAESTRIA (2026-08-01) ──────────────────
                    // Medição de produção, tudo em RAW e já com os nerfs de Knight/Paladin
                    // revertidos: knight/paladino bem upados ~110kk/h, sorcerer ~330kk/h.
                    // O multiplicador geral acima explica pouco disso — o que explodiu foi o DPS
                    // de ÁREA da Maestria, que saiu de 28 para 379 (13,5x) quando os cooldowns
                    // de 40s viraram 3s. Esta é a alavanca certa: o DANO dessas magias.
                    //
                    // ⚠️ NUNCA subir o cooldown de volta para corrigir isso. 4000ms já é DOWNGRADE
                    // em relação à Maestria II — voltaria a armadilha em que evoluir a Maestria
                    // deixava o mago mais fraco, que foi o bug que essa correção resolveu.
                    //
                    // Aplicado no VALOR FINAL, depois de qualquer caminho de fórmula (script Lua
                    // parseado ou o fallback de spellScale), justamente para não depender de qual
                    // dos dois produziu o número. Espelho no PHP: IDLE_MAESTRIA_AREA_DMG_MULT.
                    // Alvo: 330kk -> faixa de 150-180kk (pedido do dono).
                    // ⚠️ 2026-08-01: aqui a variável é `idOrWords` (o parâmetro da função), NÃO
                    // `words` — usei `words` na primeira versão e quebrou o combate em produção
                    // com "ReferenceError: words is not defined". Em runa o parâmetro é um id
                    // numérico, por isso o `isRune` no gate: só magia entra neste corte.
                    const palavrasMagia = (!isRune) ? String(idOrWords || '').toLowerCase() : '';
                    if ((dmgBaseVoc === 1 || dmgBaseVoc === 2) && palavrasMagia.includes('gran mas')) {
                        min *= 0.55;
                        max *= 0.55;
                    }

                    return Math.max(1, min + Math.random() * (max - min));
                }

formula_sources.isSpellAoe:
function isSpellAoe(words) {
                    const meta = spellsDb[words];
                    return !!(meta && meta.visual && meta.visual.area);
                }

formula_sources.getVocationRunesList:
function getVocationRunesList() {
                    const voc = playerState.vocation;
                    const baseVoc = voc > 4 ? voc - 4 : voc;
                    const allRunes = {
                        2260: { name: 'Blank Rune', vocs: [1, 2, 3], type: 'blank' },
                        2268: { name: 'Sudden Death Rune', vocs: [1, 2], type: 'attack' },
                        2273: { name: 'Ultimate Healing Rune', vocs: [1, 2, 3, 4], type: 'healing' },
                        2265: { name: 'Intense Healing Rune', vocs: [1, 2, 3, 4], type: 'healing' },
                        2304: { name: 'Great Fireball Rune', vocs: [1, 2, 3], type: 'attack' },
                        2311: { name: 'Heavy Magic Missile Rune', vocs: [1, 2, 3], type: 'attack' },
                        2287: { name: 'Light Magic Missile Rune', vocs: [1, 2, 3], type: 'attack' },
                        2313: { name: 'Explosion Rune', vocs: [1, 2, 3, 4], type: 'attack' },
                        // Runas elementais — espelho de getVocationRunes() no PHP
                        2274: { name: 'Avalanche Rune', vocs: [2, 3], type: 'attack' }, // Paladin liberado
                        2271: { name: 'Icicle Rune', vocs: [2], type: 'attack' },
                        2288: { name: 'Stone Shower Rune', vocs: [2], type: 'attack' },
                        2315: { name: 'Thunderstorm Rune', vocs: [1], type: 'attack' },
                        2302: { name: 'Fireball Rune', vocs: [1], type: 'attack' },
                        2295: { name: 'Holy Missile Rune', vocs: [3], type: 'attack' }
                    };
                    const compatible = {};
                    for (let id in allRunes) {
                        if (allRunes[id].vocs.includes(baseVoc)) {
                            compatible[id] = allRunes[id];
                        }
                    }
                    return compatible;
                }

formula_sources.getMaestriaSpellMap:
function getMaestriaSpellMap() {
                    const voc = playerState.vocation > 4 ? playerState.vocation - 4 : playerState.vocation;
                    const el = (playerState.maestriaElement || '').toLowerCase();
                    switch (voc) {
                        case 1:
                            // ALTERADO (2026-07-29): ver idleMaestriaSpellMap() no PHP — Fire Wave
                            // "gran" nova preenche o degrau do meio.
                            return el === 'energy'
                                ? { '1': 'exevo vis lux', '2': 'exevo vis hur', '3': 'exevo gran mas vis' }
                                : { '1': 'exevo flam hur', '2': 'exevo gran flam hur', '3': 'exevo gran mas flam' };
                        case 2:
                            // ALTERADO (2026-07-29): mesma mudança, espelhada pro gelo com a Ice
                            // Wave "gran" nova.
                            return el === 'earth'
                                ? { '1': 'exori gran tera', '2': 'exevo tera hur', '3': 'exevo gran mas tera' }
                                : { '1': 'exevo frigo hur', '2': 'exevo gran frigo hur', '3': 'exevo gran mas frigo' };
                        case 3: return { '1': 'exori con', '2': 'exori gran con', '3': 'exevo mas san' };
                        // ALTERADO (2026-07-28): nó 2 do Knight trocou de Exori Mas para Exori Min
                        // (Front Sweep) — ver idleMaestriaSpellMap() no PHP e o changelog "AJUSTE
                        // NO KNIGHT + MUDANÇA NA RODA DO DESTINO".
                        case 4: return { '1': 'exori', '2': 'exori min', '3': 'exori gran' };
                    }
                    return { '1': 'exori', '2': 'exori min', '3': 'exori gran' };
                }
